parameters.query:
select fonte, referencia, trecho, hash, modelo
  from conhecimento
 where referencia = $1 and fonte in ('produto', 'avaliacao');

parameters.jsCode:
// O Flask monta os textos (o mesmo código que o Python usa para indexar);
// aqui só se decide o que precisa de vetor novo, comparando o hash de cada trecho.
const flask = $('Textos do produto (Flask)').first().json;
const atuais = $input.all().map((i) => i.json).filter((r) => r.fonte);
const chave = (t) => `${t.fonte}|${t.referencia}|${t.trecho}`;
const noBanco = new Map(atuais.map((r) => [chave(r), r]));
const novos = flask.trechos.filter((t) => {
  const atual = noBanco.get(chave(t));
  return !atual || atual.hash !== t.hash || atual.modelo !== flask.modelo;
});
const validos = new Set(flask.trechos.map(chave));
const sobrando = atuais.filter((r) => !validos.has(chave(r)))
  .map((r) => ({ fonte: r.fonte, referencia: r.referencia, trecho: r.trecho }));
const modelo = flask.modelo.split('@')[0];
return [{ json: {
  produto_id: flask.produto_id, modelo: flask.modelo, dimensoes: flask.dimensoes, inicio: Date.now(),
  novos, sobrando, iguais: flask.trechos.length - novos.length,
  url_gemini: `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:batchEmbedContents`,
  pedido_gemini: { requests: novos.map((t) => ({
    model: `models/${modelo}`, content: { parts: [{ text: t.conteudo }] },
    taskType: 'RETRIEVAL_DOCUMENT', title: t.titulo, outputDimensionality: flask.dimensoes,
  })) },
} }];

// O Gemini só normaliza o vetor de 3072 dimensões; com 768 a normalização é feita aqui,
// igual ao Python (ia/gemini.py), para os vetores do n8n e do Python serem comparáveis.
const dados = $('Separar o que mudou').first().json;
const vetores = ($input.first().json.embeddings || []).map((e) => e.values);
if (vetores.length !== dados.novos.length) {
  throw new Error(`O Gemini devolveu ${vetores.length} vetores para ${dados.novos.length} trechos.`);
}
const linhas = dados.novos.map((t, i) => {
  const v = vetores[i];
  const norma = Math.sqrt(v.reduce((soma, x) => soma + x * x, 0)) || 1;
  return { fonte: t.fonte, referencia: t.referencia, trecho: t.trecho, titulo: t.titulo, conteudo: t.conteudo,
           metadados: t.metadados || {}, hash: t.hash, modelo: dados.modelo,
           embedding: '[' + v.map((x) => (x / norma).toFixed(7)).join(',') + ']' };
});
return [{ json: { quantidade: linhas.length, linhas } }];
